begin;

update public.restaurant_settings set website_mode='normal';
select 'd0000000-0000-0000-0000-000000000001',restaurant_id,'20000000-0000-0000-0000-000000000003',id,'active','Support'
from public.roles where restaurant_id='10000000-0000-0000-0000-000000000001' and slug='support-agent';
select 'd0000000-0000-0000-0000-000000000002',restaurant_id,'20000000-0000-0000-0000-000000000004',id,'active','Manager'
from public.roles where restaurant_id='10000000-0000-0000-0000-000000000001' and slug='manager';
select 'd0000000-0000-0000-0000-000000000003',restaurant_id,'20000000-0000-0000-0000-000000000008',id,'active','Developer'
from public.roles where restaurant_id='10000000-0000-0000-0000-000000000001' and slug='developer';

select restaurant_id,id,payment_method,total_minor,currency from public.orders;
select 'menu-images',object_path,'20000000-0000-0000-0000-000000000001' from public.product_images;
select 'ticket-attachments',object_path,uploaded_by::text from public.support_attachments where status='ready';
commit;
